package com.launchmate.website.domain;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * Structured description of a business website: template, theme, SEO and ordered sections.
 * Generated by AI or edited by the owner, always validated by {@link SiteConfigValidator} before
 * being stored or rendered. It contains no code and no HTML.
 */
public record SiteConfig(
        @NotBlank @Size(max = 40) String templateId,
        @NotNull @Valid Theme theme,
        @NotNull @Valid Seo seo,
        @NotNull @Size(min = 2, max = 12) List<@Valid @NotNull Section> sections) {

    public static final String HEX_COLOUR = "^#[0-9a-fA-F]{6}$";

    public SiteConfig {
        sections = sections == null ? null : List.copyOf(sections);
    }

    public SiteConfig withTemplate(String newTemplateId, Theme newTheme, List<Section> newSections) {
        return new SiteConfig(newTemplateId, newTheme, seo, newSections);
    }
}
